const GOAL = 0;
// makeEnv(start): value counts down; act({tool:"down"}) subtracts 1, observe() reads it.
function makeEnv(start) {
  let v = start;
  return { observe() { return v; }, act(a) { if (a.tool === "down") v -= 1; return v; } };
}
// policy (given): step "down" until the observation reaches GOAL, then "finish".
const policy = (obs) => obs <= GOAL ? { tool: "finish" } : { tool: "down" };
function stepToGoal(policy, env, maxSteps) {
  let obs = env.observe();
  for (let step = 0; step < maxSteps; step++) {
    const a = policy(obs);
    if (a.tool === "finish") return { halt: "goal", steps: step, obs };
    obs = env.act(a);
  }
  return { halt: "budget", steps: maxSteps, obs };
}
const a = stepToGoal(policy, makeEnv(3), 10);
console.log("run A halt:", a.halt, "steps:", a.steps, "obs:", a.obs);
const b = stepToGoal(policy, makeEnv(9), 4);
console.log("run B halt:", b.halt, "steps:", b.steps, "obs:", b.obs);

