// decide (given): search first, then read, then finish — based on what is in history.
const decide = (history) => {
  const used = history.filter((h) => h.tool_use).map((h) => h.tool_use.tool);
  if (!used.includes("search")) return { tool: "search" };
  if (!used.includes("read")) return { tool: "read" };
  return { tool: "finish" };
};
function runToAnswer(decide, env, maxSteps) {
  let history = [];
  const calls = [];
  let answer = null;
  for (let i = 0; i < maxSteps; i++) {
    const d = decide(history);
    calls.push(d.tool);
    if (d.tool === "finish") break;
    const result = env.step(d);
    if (result.text && result.text.startsWith("answer=")) answer = Number(result.text.slice(7));
    history = [...history, { tool_use: d }, { tool_result: result }];
  }
  return { answer, calls };
}
