// tasks: { id: { deps: [...], cost: n } }. The critical path is the maximum total cost
// along any dependency chain, and it sets the real duration of the whole plan.
const tasks = {
  fetch:  { deps: [],                 cost: 2 },
  clean:  { deps: ["fetch"],          cost: 3 },
  model:  { deps: ["clean"],          cost: 5 },
  chart:  { deps: ["clean"],          cost: 1 },
  report: { deps: ["model", "chart"], cost: 2 },
};
function longestPath(tasks) {
  const memo = {};
  function best(id) {
    if (memo[id]) return memo[id];
    let base = { cost: 0, path: [] };
    for (const d of tasks[id].deps) {
      const b = best(d);
      if (b.cost > base.cost) base = b;
    }
    return (memo[id] = { cost: base.cost + tasks[id].cost, path: [...base.path, id] });
  }
  let winner = { cost: 0, path: [] };
  for (const id of Object.keys(tasks)) {
    const b = best(id);
    if (b.cost > winner.cost) winner = b;
  }
  return winner;
}
const r = longestPath(tasks);
console.log("critical cost:", r.cost);
console.log("critical path:", r.path.join(" -> "));

