// A trace where the SECOND action never received an observation (its result was dropped).
const trace = [
  "Thought: find the city",
  "Action: get_profile(42)",
  "Observation: city=Oslo",
  "Thought: get the forecast",
  "Action: get_forecast(Oslo)",
  "Thought: report it",
].join("\n");
function auditTrace(raw) {
  let complete = 0;
  const dangling = [];
  let pending = null;
  for (const line of raw.split("\n")) {
    const m = line.match(/^(Thought|Action|Observation):\s*(.*)$/);
    if (!m) continue;
    const tag = m[1], val = m[2];
    if (tag === "Action") pending = val;
    if (tag === "Observation" && pending) { complete++; pending = null; }
  }
  if (pending) dangling.push(pending);
  return { complete, dangling };
}
const r = auditTrace(trace);
console.log("complete steps:", r.complete);
console.log("dangling actions:", r.dangling.join(",") || "none");

