// Each turn returns its own token cost. Stop at the FIRST budget to hit its cap, and
// report what is left of every budget when you stop.
const costs = [4, 4, 4, 4];
let t = 0;
function turn() { const c = costs[Math.min(t, costs.length - 1)]; t++; return { done: false, cost: c }; }
const budgets = { maxSteps: 10, maxTokens: 12 };
function runWithBudgets(turn, budgets) {
  let steps = 0, tokens = 0;
  const done = (halted) => ({
    halted, steps,
    remaining: { maxSteps: budgets.maxSteps - steps, maxTokens: budgets.maxTokens - tokens },
  });
  while (true) {
    if (steps >= budgets.maxSteps) return done("maxSteps");
    if (tokens >= budgets.maxTokens) return done("maxTokens");
    const r = turn();
    steps++; tokens += r.cost;
    if (r.done) return done("goal");
  }
}
const r = runWithBudgets(turn, budgets);
console.log("halted:", r.halted);
console.log("steps:", r.steps);
console.log("left steps:", r.remaining.maxSteps, "left tokens:", r.remaining.maxTokens);

