tool-errors-recovery.code:
// One tool's failures over time, in order. Retry transient errors (timeout / 5xx /
// unavailable) up to a cap; a permanent error (invalid / bad / missing) stops the call
// for good; an empty result means take a different path.
const events = ["timeout", "503 unavailable", "timeout", "invalid: bad city"];
function driveRecovery(events, cap = 3) {
  const classOf = (e) => /timeout|unavailable|5\d\d/i.test(e) ? "transient"
    : /invalid|bad|missing|4\d\d/i.test(e) ? "permanent" : "empty";
  const actions = [];
  let attempts = 0;
  for (const e of events) {
    const cls = classOf(e);
    if (cls === "transient") {
      attempts++;
      if (attempts > cap) { actions.push("abort"); break; }
      actions.push("retry");
    } else if (cls === "permanent") { actions.push("fix-args"); break; }
    else { actions.push("try-alternative"); break; }
  }
  return { actions, attempts };
}
const r = driveRecovery(events);
console.log("actions:", r.actions.join(" -> "));
console.log("attempts:", r.attempts);

