const POLLING = new Set(["poll"]);
// A different "attempt" number is a retry (progress). A "poll" tool is waiting on a job,
// never a loop. Everything else: same tool + same args + same attempt as an earlier step
// is a true repeat.
const steps = [
  { tool: "search", args: { q: "weather" }, attempt: 1 },
  { tool: "search", args: { q: "weather" }, attempt: 2 },
  { tool: "read",   args: { doc: 7 },       attempt: 1 },
  { tool: "poll",   args: { job: "j1" },    attempt: 1 },
  { tool: "poll",   args: { job: "j1" },    attempt: 1 },
  { tool: "search", args: { q: "weather" }, attempt: 1 },
];
function findLoop(steps, polling) {
  const seen = new Set();
  for (let i = 0; i < steps.length; i++) {
    const s = steps[i];
    if (polling.has(s.tool)) continue;
    const args = Object.keys(s.args).sort().map((k) => k + "=" + s.args[k]).join(",");
    const fp = s.tool + "(" + args + ")#" + s.attempt;
    if (seen.has(fp)) return i;
    seen.add(fp);
  }
  return -1;
}
const at = findLoop(steps, POLLING);
console.log("first loop at index:", at);
console.log("looping step:", at >= 0 ? steps[at].tool : "none");

argument-validation-bounding.code:
const schema = {
  properties: {
    q:     { type: "string", maxLen: 8 },
    limit: { type: "number", max: 50 },
    order: { type: "string", enum: ["asc", "desc"] },
  },
  required: ["q", "limit"],
};
const calls = [
  { input: { q: "wildfires today", limit: 10, order: "asc" } },
  { input: { q: "cats", limit: 999 } },
  { input: { q: "dogs", limit: 5, order: "sideways" } },
  { input: { limit: 5 } },
];
function checkAndClamp(call, schema) {
  const inp = call.input || {};
  const errors = [];
  for (const req of schema.required) if (!(req in inp)) errors.push("missing " + req);
  for (const [k, spec] of Object.entries(schema.properties)) {
    if (!(k in inp)) continue;
    if (spec.type === "number" && typeof inp[k] !== "number") errors.push(k + " not a number");
    if (spec.enum && !spec.enum.includes(inp[k])) errors.push(k + " not in enum");
  }
  if (errors.length) return { ok: false, errors };
  const out = {};
  for (const [k, v] of Object.entries(inp)) {
    const spec = schema.properties[k] || {};
    if (spec.type === "number" && typeof spec.max === "number") out[k] = Math.min(v, spec.max);
    else if (spec.type === "string" && typeof spec.maxLen === "number") out[k] = v.slice(0, spec.maxLen);
    else out[k] = v;
  }
  return { ok: true, input: out };
}
for (const c of calls) {
  const r = checkAndClamp(c, schema);
  if (r.ok) console.log("ok q=" + r.input.q + " limit=" + r.input.limit);
  else console.log("reject: " + r.errors.join(", "));
}

