// Thread each step's output into the next via ctx. An optional step may fail (skip it and
// continue); a required step failing halts the pipeline.
const steps = [
  { name: "fetch",   optional: false, run: (ctx) => ({ value: 10 }) },
  { name: "enrich",  optional: true,  run: (ctx) => ({ error: "enrich API down" }) },
  { name: "double",  optional: false, run: (ctx) => ({ value: ctx.fetch * 2 }) },
  { name: "publish", optional: false, run: (ctx) => ({ value: "published:" + ctx.double }) },
];
function runPipeline(steps) {
  const ctx = {};
  const skipped = [];
  for (const s of steps) {
    const out = s.run(ctx);
    if (out.error) {
      if (s.optional) { skipped.push(s.name); continue; }
      return { ok: false, failedAt: s.name, ctx, skipped };
    }
    ctx[s.name] = out.value;
  }
  return { ok: true, ctx, skipped };
}
const r = runPipeline(steps);
console.log("ok:", r.ok);
console.log("skipped:", r.skipped.join(",") || "none");
console.log("result:", r.ctx.publish);

