// Fold writes into a store keyed "worker.key". If the SAME worker writes the SAME key
// again, the later value wins — record that namespaced key as overwritten.
const writes = [
  { worker: "research", key: "result", value: "found 42" },
  { worker: "code",     key: "result", value: "wrote loop()" },
  { worker: "research", key: "result", value: "found 43" },
  { worker: "code",     key: "status", value: "done" },
];
function foldWrites(writes) {
  const store = {};
  const overwritten = [];
  for (const w of writes) {
    const ns = w.worker + "." + w.key;
    if (ns in store) overwritten.push(ns);
    store[ns] = w.value;
  }
  return { store, overwritten };
}
