const deltas = [5, 5, 5, 5];
function lostUpdates(start, deltas) {
  const correct = deltas.reduce((a, d) => a + d, start);
  let naive = start;
  for (const d of deltas) naive = start + d;   // every worker read the SAME start snapshot
  return { correct, naive, lost: correct - naive };
}
const r = lostUpdates(start, deltas);
