const rubric = { goal: 100, optimalSteps: 3, stepPenalty: 5, repeatPenalty: 10, disallowedPenalty: 40, allowedTools: ["search", "read", "finish"] };
const runs = {
  A: { goalReached: true, steps: 3, repeats: 0, toolsUsed: ["search", "read", "finish"] },
  B: { goalReached: true, steps: 6, repeats: 1, toolsUsed: ["search", "read", "finish"] },
  C: { goalReached: true, steps: 4, repeats: 0, toolsUsed: ["search", "delete", "finish"] },
};
function rankRuns(runs, rubric) {
  const scores = {};
  for (const [name, log] of Object.entries(runs)) {
    let s = log.goalReached ? rubric.goal : 0;
    s -= Math.max(0, log.steps - rubric.optimalSteps) * rubric.stepPenalty;
    s -= log.repeats * rubric.repeatPenalty;
    const bad = log.toolsUsed.filter((tool) => !rubric.allowedTools.includes(tool));
    s -= bad.length * rubric.disallowedPenalty;
    scores[name] = s;
  }
  const ranked = Object.entries(scores).sort((a, b) => b[1] - a[1]);
  return { winner: ranked[0][0], best: ranked[0][1], margin: ranked[0][1] - ranked[1][1], scores };
}
const r = rankRuns(runs, rubric);
console.log("scores:", ["A", "B", "C"].map((n) => n + "=" + r.scores[n]).join(" "));
console.log("winner:", r.winner, "margin:", r.margin);

