const grant = { search: ["read"], send_email: ["write"], finish: ["read"] };  // least privilege
const GATED = new Set(["send_email"]);                            // high-impact: ask a human
function permit(a) { return !!grant[a.tool]; }
function checkArgs(a) {
  if (a.tool === "search") return typeof a.args.q === "string" && a.args.q.length <= 64;
  return true;
}
function approve() { return false; }
const script = [
  { tool: "search", args: { q: "q3 revenue" } },
  { tool: "search", args: { q: "x".repeat(200) } },
  { tool: "delete", args: { id: 1 } },
  { tool: "send_email", args: { to: "ops@acme.com" } },
  { tool: "finish", args: {} },
];
let i = 0;
const scripted = () => script[Math.min(i++, script.length - 1)];
function runSafeAgent(policy, budget) {
  const log = { turns: 0, steps: 0, repeats: 0, toolsUsed: [], goalReached: false,
                denied: [], invalid: [], gated: [] };
  const seen = new Set();
  while (log.turns < budget.maxTurns) {
    log.turns++;                                   // spent at the TOP: denials count against the budget
    const a = policy();
    if (!permit(a)) { log.denied.push(a.tool); continue; }
    if (!checkArgs(a)) { log.invalid.push(a.tool); continue; }
    const fp = a.tool + JSON.stringify(a.args || {});
    if (seen.has(fp)) { log.repeats++; break; }
    seen.add(fp);
    if (GATED.has(a.tool)) { log.gated.push(a.tool); if (!approve(a)) continue; }
    log.steps++; log.toolsUsed.push(a.tool);
    if (a.tool === "finish") { log.goalReached = true; break; }
  }
  return log;
}
function score(log) {
  return (log.goalReached ? 100 : 0)
    - (log.denied.length + log.invalid.length) * 20
    - log.repeats * 10
    - Math.max(0, log.steps - 2) * 5;
}
const log = runSafeAgent(scripted, { maxTurns: 10 });
console.log("goalReached:", log.goalReached);
console.log("denied:", log.denied.join(",") || "none");
console.log("invalid:", log.invalid.join(",") || "none");
console.log("gated:", log.gated.join(",") || "none");
console.log("steps:", log.steps, "turns:", log.turns, "score:", score(log));
const stubborn = runSafeAgent(() => ({ tool: "delete", args: { id: 1 } }), { maxTurns: 6 });
console.log("stubborn denied run: turns", stubborn.turns, "steps", stubborn.steps,
            "denied", stubborn.denied.length, "goalReached", stubborn.goalReached);
const stuck = runSafeAgent(() => ({ tool: "search", args: { q: "same" } }), { maxTurns: 10 });
console.log("guard tripped run: repeats", stuck.repeats, "turns", stuck.turns, "steps", stuck.steps);
